"use client";

// The Trade Room (Mayank Raj, @thetraderoomsss) study of 15 Nov 2026: every video read, the strategies found in them
// with their rules (E stated / I inferred / A our assumption, each stated rule with its quote and video time), what the
// videos leave missing or ambiguous, and the strategies not coded and why. Data: ./traderoomData.ts, generated by
// backend/research/youtube_traderoom_2026_11/zt_export.py. The coded strategies paper trade on the desk (source
// youtube_traderoom, Rs 10 lakh each, simulated orders on real prices); each card shows its account through
// ShortlistPaper (capital, equity, net P&L after the engine's fees and slippage, return, win rate, maximum drawdown, open
// and closed trades, each book's state and the trade history). Paper only: nothing here can place an order.
import { useMemo } from "react";
import GlassPanel from "../../components/GlassPanel";
import type { Account, Summary } from "./PaperDesk";
import { SEG_PLACE, type SegFocus, type SegId } from "./Segments";
import ShortlistPaper, { type ShortlistBook } from "./ShortlistPaper";
import { TR, TR_META, TR_VIDEOS, type TrRule, type TrStrategy, type TrTime } from "./traderoomData";

const STUDY = "youtube_traderoom";
type OpenFn = (f: Omit<SegFocus, "at">) => void;
type Book = ShortlistBook & { segment?: string };
const isSeg = (s?: string): s is SegId => !!s && s in SEG_PLACE;
const LABEL = Object.fromEntries(TR_VIDEOS.map((v) => [v.id, v.label])) as Record<string, string>;
const KIND = { teaching: "Teaching", live: "Live session", short: "Short", skipped: "Not read" } as Record<string, string>;

function sec(t: string): number {
  const p = t.split(":").map(Number);
  return p.length === 3 ? p[0] * 3600 + p[1] * 60 + p[2] : p[0] * 60 + p[1];
}

const istTime = (iso: string) =>
  new Date(iso).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", dateStyle: "medium", timeStyle: "short" });

/** Video times as links that open the video at that second; a time in another video carries that video's name. */
function Times({ main, times }: { main: string; times: (TrTime | null)[] }) {
  const ts = times.filter((t): t is TrTime => !!t);
  if (!ts.length) return null;
  return (
    <span className="trm-times">
      {ts.map((t, i) => (
        <a key={`${t.v}-${t.t}-${i}`} href={`https://youtu.be/${t.v}?t=${sec(t.t)}`} target="_blank" rel="noreferrer">
          {t.v === main ? t.t : `${LABEL[t.v] ?? t.v} ${t.t}`}
        </a>
      ))}
    </span>
  );
}

function grouped(rules: TrRule[]): [string, TrRule[]][] {
  const out: [string, TrRule[]][] = [];
  for (const r of rules) {
    const last = out[out.length - 1];
    if (last && last[0] === r.label) last[1].push(r);
    else out.push([r.label, [r]]);
  }
  return out;
}

function Card({ s, account, books, onOpen }: { s: TrStrategy; account?: Account; books?: Book[]; onOpen?: OpenFn }) {
  const stated = s.rules.filter((r) => r.tag !== "A");
  const ours = s.rules.filter((r) => r.tag === "A");
  const gaps = s.vague.length + s.unclear.length;
  const segs = Array.from(new Set((books ?? []).map((b) => b.segment).filter(isSeg)));
  return (
    <div className="ps-card trm-card">
      <div className="ps-card-top">
        <span className="ps-fam up">{s.id} · {s.version}</span>
        <span className="trm-dim">The Trade Room (Mayank Raj)</span>
      </div>
      <div className="ps-card-name">{s.name}</div>
      <div className="trm-line">{s.markets.join(" · ")} · {s.timeframes.join(", ")} · intraday</div>
      <div className="trm-line">
        Source video: <a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.title || s.video}</a>
        <span className="trm-dim">{s.uploaded ? ` · ${s.uploaded}` : ""}{s.minutes ? ` · ${s.minutes} min` : ""}</span>
      </div>
      <p className="trm-sum">{s.summary}</p>
      <div className="trm-tags">
        <span className={`trm-tag ${s.readiness === "ready" ? "ok" : "warn"}`}>{s.readiness === "ready" ? "Every rule stated" : "Coded with documented assumptions"}</span>
        {s.checks && (
          <span className={`trm-tag ${s.checks.lookahead && s.checks.fills ? "ok" : "bad"}`}>
            {s.checks.lookahead && s.checks.fills ? "Look-ahead and fill checks passed" : "Code check failed"}
          </span>
        )}
        <span className="trm-tag">Not backtested</span>
      </div>
      <ShortlistPaper status="coded" account={account} books={books} start={s.paperStart ?? TR_META.paperStart} />
      {onOpen && segs.length > 0 && (
        <div className="trm-open">
          {segs.map((g) => (
            <button key={g} className="trm-openbtn" onClick={() => onOpen({ seg: g, study: STUDY, book: (books ?? []).find((b) => b.segment === g) ? `${s.id}|${(books ?? []).find((b) => b.segment === g)!.mkt}` : undefined })}>
              {`Open in ${SEG_PLACE[g].label} →`}
            </button>
          ))}
        </div>
      )}
      <details className="trm-sec">
        <summary>Rules from the videos ({stated.length})</summary>
        {grouped(stated).map(([label, rs]) => (
          <div key={label} className="trm-group">
            <div className="trm-glabel">{label}</div>
            <ul className="trm-rules">
              {rs.map((r, i) => (
                <li key={i}>
                  <span className={`trm-t ${r.tag}`}>{r.tag}</span> {r.text} <Times main={s.video} times={r.times} />
                  {r.quote ? <span className="trm-quote">{` “${r.quote}”`}</span> : null}
                </li>
              ))}
            </ul>
          </div>
        ))}
        <p className="trm-dim">E = stated in the video · I = inferred from his words · quotes are his Hindi captions, romanized.</p>
      </details>
      {ours.length > 0 && (
        <details className="trm-sec">
          <summary>Our assumptions used to code it ({ours.length})</summary>
          <ul className="trm-rules">
            {ours.map((r, i) => <li key={i}><span className="trm-t A">A</span> <b>{r.label}:</b> {r.text}</li>)}
          </ul>
          <p className="trm-dim">{"These are the research team's choices, not the creator's words: they fill the gaps the videos leave so the rule can run."}</p>
        </details>
      )}
      {gaps > 0 && (
        <details className="trm-sec">
          <summary>Missing or ambiguous in the videos ({gaps})</summary>
          <ul className="trm-rules">
            {s.vague.map((v, i) => (
              <li key={`v${i}`}>
                {`“${v.term}”`} <Times main={s.video} times={[v.at]} />{`: ${v.why}. Coded as: ${v.coded}.`}
              </li>
            ))}
            {s.unclear.map((u, i) => <li key={`u${i}`}>{`Open question: ${u}`}</li>)}
          </ul>
        </details>
      )}
      {(s.claims.length > 0 || s.examples.length > 0) && (
        <details className="trm-sec">
          <summary>Claims and examples in the videos ({s.claims.length + s.examples.length})</summary>
          <ul className="trm-rules">
            {s.claims.map((c, i) => <li key={`c${i}`}>{`Claim: ${c.value}${c.period ? ` (${c.period})` : ""}`} <Times main={s.video} times={[c.at]} /></li>)}
            {s.examples.map((x, i) => (
              <li key={`x${i}`}>
                {`Example${x.date ? ` ${x.date}` : ""}: ${x.instrument} ${x.direction}, ${x.setup}; entry ${x.entry || "—"}, stop ${x.stop || "—"}, target ${x.target || "—"} → ${x.outcome}`}{" "}
                <Times main={s.video} times={[x.at]} />
              </li>
            ))}
          </ul>
          <p className="trm-dim">Quoted as said and not verified.</p>
        </details>
      )}
      <div className="trm-dim">{`Not a duplicate: ${s.duplicateCheck}`}</div>
      {s.checks && <div className="trm-dim">{`Code check on research data: ${s.checks.signals} signals, ${s.checks.trades} simulated fills (a correctness check, not a result).`}</div>}
    </div>
  );
}

export default function TradeRoom({ summary, onOpen }: { summary: Summary | null; error?: string | null; onOpen?: OpenFn }) {
  const byId = useMemo(() => Object.fromEntries((summary?.accounts ?? []).map((a) => [a.id, a])) as Record<string, Account>, [summary]);
  const booksById = ((summary?.status as { books?: Record<string, Book[]> } | undefined)?.books ?? {});
  const m = TR_META;
  const coded = TR.filter((s) => s.status === "coded");
  const other = TR.filter((s) => s.status !== "coded");
  const onDesk = coded.filter((s) => byId[s.id]).length;
  return (
    <>
      <GlassPanel title="The Trade Room (Mayank Raj) — strategies from his videos" note={`${m.coded} coded · paper trading · ₹10 lakh each`}>
        <p className="trm-intro">
          {`${m.read} of the channel's videos were read in full from their transcripts: ${m.teaching} teaching videos, ${m.lives} live gold and crypto sessions and ${m.shorts} shorts (${m.skipped} more were skipped: a desk tour, an option Greeks explainer and two market forecasts). `}
          {`They hold ${m.coded} strategies clear enough to code, each written as exact rules (version v1) with every stated rule linked to its moment in the video; ${m.blocked} more are left out because the videos never fix their rules, and his best-known strategy (TR-01) is already in the app. `}
          {`All ${m.checked} coded strategies passed the look-ahead and fill checks; none is backtested. Each paper trades its own ₹10 lakh account from ${istTime(m.paperStart)} IST, flat, with simulated orders on real prices: gold and bitcoin from Delta Exchange (XAUTUSD, BTCUSD), Nifty and Bank Nifty from the desk's Angel One index minutes. Profit and loss is net of the engine's estimated fees, spread and slippage. No real order is ever placed.`}
          {summary ? ` ${onDesk} of ${m.coded} accounts are on the desk.` : ""}
        </p>
      </GlassPanel>
      <div className="ps-cards trm-cards">
        {coded.map((s) => <Card key={s.id} s={s} account={byId[s.id]} books={booksById[s.id]} onOpen={onOpen} />)}
      </div>
      <GlassPanel title="No account of their own" note="rules incomplete, or already in the app">
        <ul className="trm-list">
          {other.map((s) => (
            <li key={s.id}>
              <b>{`${s.id} ${s.name}`}</b>{" "}
              (<a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{LABEL[s.video] ?? s.video}</a>
              <Times main="" times={s.cites} />){" "}
              <ShortlistPaper status={s.status === "duplicate" ? "duplicate" : "blocked"} start={TR_META.paperStart}
                blockedReason={s.reason} dataBlocked={false} duplicateOf={s.duplicateOf} duplicateWhy={s.reason} />
            </li>
          ))}
        </ul>
      </GlassPanel>
      <details className="trm-sec trm-wide">
        <summary>{`Every video read (${m.read}) and what it gave`}</summary>
        <table className="trm-table">
          <thead><tr><th>Video</th><th>Kind</th><th>Date</th><th>Min</th><th>What it gave</th></tr></thead>
          <tbody>
            {TR_VIDEOS.map((v) => (
              <tr key={v.id}>
                <td><a href={`https://youtu.be/${v.id}`} target="_blank" rel="noreferrer">{v.title || v.id}</a></td>
                <td>{KIND[v.kind] ?? v.kind}</td>
                <td>{v.uploaded || "—"}</td>
                <td>{v.minutes || "—"}</td>
                <td>{v.gave}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
      {/* global: the cards are child components; every selector is trm-prefixed, so nothing outside this tab is touched. */}
      <style jsx global>{`
        .trm-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0; }
        .trm-cards { align-items: start; margin: 14px 0 16px; }
        .trm-line { font-size: 12.5px; line-height: 1.5; overflow-wrap: anywhere; }
        .trm-dim { color: var(--text-muted); font-size: 11.5px; }
        .trm-sum { font-size: 12.5px; line-height: 1.55; margin: 0; color: var(--text-secondary); }
        .trm-tags { display: flex; flex-wrap: wrap; gap: 6px; }
        .trm-tag { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); }
        .trm-tag.ok { border-color: var(--gain); color: var(--gain); }
        .trm-tag.warn { border-color: var(--warn-border); color: var(--warn); }
        .trm-tag.bad { border-color: var(--loss); color: var(--loss); }
        .trm-open { display: flex; flex-wrap: wrap; gap: 6px; }
        .trm-openbtn { font-size: 11.5px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--panel-border);
          background: transparent; color: var(--purple); cursor: pointer; }
        .trm-sec { font-size: 12.5px; }
        .trm-sec summary { cursor: pointer; font-weight: 600; }
        .trm-wide { margin: 8px 0 16px; }
        .trm-group { margin-top: 6px; }
        .trm-glabel { font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
        .trm-rules { margin: 4px 0 6px; padding-left: 18px; line-height: 1.55; }
        .trm-rules li { margin-bottom: 4px; overflow-wrap: anywhere; }
        .trm-quote { color: var(--text-muted); font-style: italic; font-size: 11.5px; }
        .trm-t { display: inline-block; min-width: 16px; text-align: center; font-size: 10px; font-weight: 800; border-radius: 4px; padding: 0 3px;
          border: 1px solid var(--panel-border); color: var(--text-muted); }
        .trm-t.E { border-color: var(--gain); color: var(--gain); }
        .trm-t.I { border-color: var(--purple); color: var(--purple); }
        .trm-t.A { border-color: var(--warn-border); color: var(--warn); }
        .trm-times a { margin-left: 6px; font-size: 11px; font-variant-numeric: tabular-nums; }
        .trm-list { font-size: 12.5px; line-height: 1.6; padding-left: 18px; margin: 0; }
        .trm-list li { margin-bottom: 8px; overflow-wrap: anywhere; }
        .trm-table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }
        .trm-table th, .trm-table td { text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--panel-border); vertical-align: top; }
      `}</style>
    </>
  );
}
